using System;using System.IO;using System.Linq;using System.IO.Compression;using System.Reflection;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using BongoChat;
public static class JsonRuntimeTests
{
 static int checks;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 [STAThread]public static int Main(string[] args){try{
  string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);AppStorage.Root=root;string game=Path.Combine(root,"game");Directory.CreateDirectory(Path.Combine(game,"BongoCat_Data","Managed"));File.WriteAllText(Path.Combine(game,"BongoCat.exe"),"fake game");File.WriteAllText(Path.Combine(game,"BongoCat_Data","Managed","Assembly-CSharp.dll"),"game original");string originalJson=Path.Combine(game,"BongoCat_Data","Managed","Newtonsoft.Json.dll");File.WriteAllText(originalJson,"game original JSON sentinel");
  using(var stream=typeof(ChatWindow).Assembly.GetManifestResourceStream("BongoChat.SetupPayload"))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){Check(zip.GetEntry("runtime/BepInEx/unstripped/Newtonsoft.Json.dll")!=null,"single EXE embeds the full JSON compatibility runtime");}
  BridgeSetup.Install(game,null);string file=Path.Combine(game,"BepInEx","unstripped","Newtonsoft.Json.dll"),expected="C5C83BBC1741BE6FF4C490C0AEE34C162945423EC577C646538B2D21CE13199E";Check(BridgeSetup.FileHash(file)==expected,"installed compatibility DLL matches the official NuGet net45 binary");
  var name=AssemblyName.GetAssemblyName(file);Check(name.Version==new Version(13,0,0,0)&&BitConverter.ToString(name.GetPublicKeyToken()).Replace("-","").ToLowerInvariant()=="30ad4fe6b2a6aeed","replacement assembly identity matches the game's JSON major and public key");
  string probe=Path.Combine(Path.GetDirectoryName(typeof(ChatWindow).Assembly.Location),"JsonRuntimeProbe.exe");var info=new ProcessStartInfo(probe,DesktopInstall.QuoteArgument(file)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var child=Process.Start(info)){Check(child.WaitForExit(15000),"isolated JSON compatibility probe completes");string output=child.StandardOutput.ReadToEnd()+child.StandardError.ReadToEnd();Check(child.ExitCode==0&&output.Contains("PASS JObject/JArray"),"JObject and JArray creation Unicode parsing and full interface contracts work in a clean process");}
  Check(File.ReadAllText(originalJson)=="game original JSON sentinel"&&File.ReadAllText(Path.Combine(game,"BongoCat_Data","Managed","Assembly-CSharp.dll"))=="game original","compatibility setup preserves every original game assembly");
  string record=Path.Combine(game,"BepInEx","BongoChat","room_123.jsonl");Directory.CreateDirectory(Path.GetDirectoryName(record));File.WriteAllText(record,"private journal sentinel");string manifestPath=Path.Combine(game,"BongoChat-install.json");var manifest=Journal.Json.Deserialize<InstallManifest>(File.ReadAllText(manifestPath));Check(manifest.files.Any(x=>x.relative.EndsWith("unstripped\\Newtonsoft.Json.dll")),"JSON compatibility file has explicit installation ownership");manifest.version="0.2.4";manifest.files=manifest.files.Where(x=>!x.relative.EndsWith("unstripped\\Newtonsoft.Json.dll")).ToArray();File.WriteAllText(manifestPath,Journal.Json.Serialize(manifest));File.Delete(file);Check(BridgeSetup.Inspect(game).NeedsInstall,"old complete installation is detected as needing the additional JSON runtime");BridgeSetup.Install(game,null);Check(!BridgeSetup.Inspect(game).NeedsInstall&&BridgeSetup.FileHash(file)==expected&&File.ReadAllText(record)=="private journal sentinel","owned upgrade adds the runtime without changing conversations");var written=File.GetLastWriteTimeUtc(file);BridgeSetup.Install(game,null);Check(File.GetLastWriteTimeUtc(file)==written,"a verified JSON compatibility install is idempotent");
  BridgeSetup.SetConnectionPaused(game,true);Directory.CreateDirectory(Path.Combine(game,"BepInEx","BongoChat"));File.WriteAllText(Path.Combine(game,"BepInEx","BongoChat","state.json"),Journal.Json.Serialize(new BridgeState{protocol=1,version=BridgeSetup.RequiredBridgeVersion,ready=true,canSend=true,session="paused-test",room="123",utc=DateTime.UtcNow.ToString("o")}));TabletCompatibility.Configure();new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new ChatWindow(false,game,true,"ko");typeof(ChatWindow).GetField("automaticSetupEnabled",flags).SetValue(window,true);typeof(ChatWindow).GetMethod("Reconnect",flags).Invoke(window,null);Check(BridgeSetup.IsConnectionPaused(game)&&!File.Exists(Path.Combine(game,"winhttp.dll")),"ordinary Reconnect never restores a deliberately paused loader");Check(!(bool)typeof(ChatWindow).GetField("setupBusy",flags).GetValue(window)&&(string)typeof(ChatWindow).GetField("setupAction",flags).GetValue(window)=="resume","paused Reconnect only exposes the explicit restoration action without opening a restart dialog");Check(!(bool)typeof(ChatWindow).GetField("canSend",flags).GetValue(window)&&!((DispatcherTimer)typeof(ChatWindow).GetField("reconnectTimer",flags).GetValue(window)).IsEnabled,"paused reconnect cannot send or start a connection poll loop");window.Close();Application.Current.Shutdown();
  BridgeSetup.SetConnectionPaused(game,false);File.WriteAllText(file,"externally changed JSON");Check(BridgeSetup.Inspect(game).Problem!=null,"a third-party modified JSON runtime is detected");bool rejected=false;try{BridgeSetup.Install(game,null);}catch(IOException){rejected=true;}Check(rejected&&File.ReadAllText(file)=="externally changed JSON","automatic repair preserves an externally modified runtime");
  Console.WriteLine("All "+checks+" JSON runtime checks passed.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);if(Application.Current!=null)Application.Current.Shutdown();return 1;}}
}